\set ON_ERROR_STOP on
-- Run only against an empty disposable PostgreSQL 18 database.
CREATE SCHEMA domain;
SET search_path TO domain;
\ir ../../../backend/blocbuy-bootstrap/src/main/resources/db/migration/V5__groupbuy.sql
INSERT INTO biz_group_deal
(id, deal_no, product_id, leader_user_id, deal_price, currency, target_size, current_size, status, start_time, expire_time)
SELECT md5(n::text)::uuid, 'DEAL-' || n,
       ('a0000000-0000-7000-8000-' || lpad((((n - 1) / 400) + 1)::text, 12, '0'))::uuid,
       'c0000000-0000-7000-8000-000000000001'::uuid,
       10 + (n % 200), 'sgd', 3, 1, 'open', CURRENT_TIMESTAMP - INTERVAL '1 hour',
       CURRENT_TIMESTAMP + INTERVAL '1 day'
FROM generate_series(1, 10000) AS n;
ANALYZE biz_group_deal;
SELECT version();
SELECT COUNT(*) AS fixture_total_rows, COUNT(DISTINCT product_id) AS fixture_products FROM biz_group_deal;
SELECT COUNT(*) AS before_returned_rows FROM (SELECT id, deal_no, product_id, leader_user_id, deal_price, currency, target_size, current_size, status, start_time, expire_time, success_time, create_time, create_by, update_time, update_by, deleted, version FROM biz_group_deal WHERE deleted = false AND status = 'open' AND expire_time > CURRENT_TIMESTAMP AND product_id IN ('a0000000-0000-7000-8000-000000000001'::uuid, 'a0000000-0000-7000-8000-000000000002'::uuid, 'a0000000-0000-7000-8000-000000000003'::uuid, 'a0000000-0000-7000-8000-000000000004'::uuid, 'a0000000-0000-7000-8000-000000000005'::uuid, 'a0000000-0000-7000-8000-000000000006'::uuid, 'a0000000-0000-7000-8000-000000000007'::uuid, 'a0000000-0000-7000-8000-000000000008'::uuid, 'a0000000-0000-7000-8000-000000000009'::uuid, 'a0000000-0000-7000-8000-000000000010'::uuid, 'a0000000-0000-7000-8000-000000000011'::uuid, 'a0000000-0000-7000-8000-000000000012'::uuid, 'a0000000-0000-7000-8000-000000000013'::uuid, 'a0000000-0000-7000-8000-000000000014'::uuid, 'a0000000-0000-7000-8000-000000000015'::uuid, 'a0000000-0000-7000-8000-000000000016'::uuid, 'a0000000-0000-7000-8000-000000000017'::uuid, 'a0000000-0000-7000-8000-000000000018'::uuid, 'a0000000-0000-7000-8000-000000000019'::uuid, 'a0000000-0000-7000-8000-000000000020'::uuid)) q;
SELECT COUNT(*) AS after_returned_rows FROM (SELECT DISTINCT ON (product_id) id, deal_no, product_id, leader_user_id, deal_price, currency, target_size, current_size, status, start_time, expire_time, success_time, create_time, create_by, update_time, update_by, deleted, version FROM biz_group_deal WHERE deleted = false AND status = 'open' AND expire_time > CURRENT_TIMESTAMP AND product_id IN ('a0000000-0000-7000-8000-000000000001'::uuid, 'a0000000-0000-7000-8000-000000000002'::uuid, 'a0000000-0000-7000-8000-000000000003'::uuid, 'a0000000-0000-7000-8000-000000000004'::uuid, 'a0000000-0000-7000-8000-000000000005'::uuid, 'a0000000-0000-7000-8000-000000000006'::uuid, 'a0000000-0000-7000-8000-000000000007'::uuid, 'a0000000-0000-7000-8000-000000000008'::uuid, 'a0000000-0000-7000-8000-000000000009'::uuid, 'a0000000-0000-7000-8000-000000000010'::uuid, 'a0000000-0000-7000-8000-000000000011'::uuid, 'a0000000-0000-7000-8000-000000000012'::uuid, 'a0000000-0000-7000-8000-000000000013'::uuid, 'a0000000-0000-7000-8000-000000000014'::uuid, 'a0000000-0000-7000-8000-000000000015'::uuid, 'a0000000-0000-7000-8000-000000000016'::uuid, 'a0000000-0000-7000-8000-000000000017'::uuid, 'a0000000-0000-7000-8000-000000000018'::uuid, 'a0000000-0000-7000-8000-000000000019'::uuid, 'a0000000-0000-7000-8000-000000000020'::uuid) ORDER BY product_id ASC, deal_price ASC, id ASC) q;
\echo 'BEFORE: full matching rows'
EXPLAIN (ANALYZE, BUFFERS) SELECT id, deal_no, product_id, leader_user_id, deal_price, currency, target_size, current_size, status, start_time, expire_time, success_time, create_time, create_by, update_time, update_by, deleted, version FROM biz_group_deal WHERE deleted = false AND status = 'open' AND expire_time > CURRENT_TIMESTAMP AND product_id IN ('a0000000-0000-7000-8000-000000000001'::uuid, 'a0000000-0000-7000-8000-000000000002'::uuid, 'a0000000-0000-7000-8000-000000000003'::uuid, 'a0000000-0000-7000-8000-000000000004'::uuid, 'a0000000-0000-7000-8000-000000000005'::uuid, 'a0000000-0000-7000-8000-000000000006'::uuid, 'a0000000-0000-7000-8000-000000000007'::uuid, 'a0000000-0000-7000-8000-000000000008'::uuid, 'a0000000-0000-7000-8000-000000000009'::uuid, 'a0000000-0000-7000-8000-000000000010'::uuid, 'a0000000-0000-7000-8000-000000000011'::uuid, 'a0000000-0000-7000-8000-000000000012'::uuid, 'a0000000-0000-7000-8000-000000000013'::uuid, 'a0000000-0000-7000-8000-000000000014'::uuid, 'a0000000-0000-7000-8000-000000000015'::uuid, 'a0000000-0000-7000-8000-000000000016'::uuid, 'a0000000-0000-7000-8000-000000000017'::uuid, 'a0000000-0000-7000-8000-000000000018'::uuid, 'a0000000-0000-7000-8000-000000000019'::uuid, 'a0000000-0000-7000-8000-000000000020'::uuid);
\echo 'AFTER: one best row per product'
EXPLAIN (ANALYZE, BUFFERS) SELECT DISTINCT ON (product_id) id, deal_no, product_id, leader_user_id, deal_price, currency, target_size, current_size, status, start_time, expire_time, success_time, create_time, create_by, update_time, update_by, deleted, version FROM biz_group_deal WHERE deleted = false AND status = 'open' AND expire_time > CURRENT_TIMESTAMP AND product_id IN ('a0000000-0000-7000-8000-000000000001'::uuid, 'a0000000-0000-7000-8000-000000000002'::uuid, 'a0000000-0000-7000-8000-000000000003'::uuid, 'a0000000-0000-7000-8000-000000000004'::uuid, 'a0000000-0000-7000-8000-000000000005'::uuid, 'a0000000-0000-7000-8000-000000000006'::uuid, 'a0000000-0000-7000-8000-000000000007'::uuid, 'a0000000-0000-7000-8000-000000000008'::uuid, 'a0000000-0000-7000-8000-000000000009'::uuid, 'a0000000-0000-7000-8000-000000000010'::uuid, 'a0000000-0000-7000-8000-000000000011'::uuid, 'a0000000-0000-7000-8000-000000000012'::uuid, 'a0000000-0000-7000-8000-000000000013'::uuid, 'a0000000-0000-7000-8000-000000000014'::uuid, 'a0000000-0000-7000-8000-000000000015'::uuid, 'a0000000-0000-7000-8000-000000000016'::uuid, 'a0000000-0000-7000-8000-000000000017'::uuid, 'a0000000-0000-7000-8000-000000000018'::uuid, 'a0000000-0000-7000-8000-000000000019'::uuid, 'a0000000-0000-7000-8000-000000000020'::uuid) ORDER BY product_id ASC, deal_price ASC, id ASC;
